function permutations(items) {
  const answers = [];
  const current = [];
  const used = new Array(items.length).fill(false);

  function solve() {
    if (current.length === items.length) {
      answers.push([...current]);
      return;
    }

    for (let i = 0; i < items.length; i++) {
      if (used[i]) continue;          // already placed somewhere above

      used[i] = true;                 // choose
      current.push(items[i]);
      solve();                        // explore
      current.pop();                  // un-choose, both halves
      used[i] = false;
    }
  }

  solve();
  return answers;
}
